import {installGameUI} from './game-ui.js';
import {createArtifactChat} from './chat-widget.js';
import {artifacts,sources,answerQuestion,suggestions,gradeInvestigation} from './data.js';
import {stories} from './stories.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M7 17 17 7M7 7h10v10',right:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M6 18 18 6',menu:'M4 7h16M4 12h16M4 17h16',check:'m5 12 4 4L19 6',play:'m8 5 12 7-12 7Z',book:'M4 4h7v16H4ZM13 4h7v16h-7',globe:'M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z',cube:'m12 3 9 5v9l-9 5-9-5V8Zm0 9 9-4M12 12 3 8m9 4v10',scan:'M8 3H3v5M16 3h5v5M3 16v5h5m13-5v5h-5M7 12h10M12 7v10',sound:'m4 9 5 0 5-5v16l-5-5H4ZM18 8c3 3 3 5 0 8',reset:'M4 10a8 8 0 1 1 1 8M4 4v6h6',send:'m3 3 19 9-19 9 4-9Zm4 9h15',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM14 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
let passport={};try{passport=JSON.parse(localStorage.getItem('echoes-passport')||'{}');if(!passport||typeof passport!=='object'||Array.isArray(passport))passport={};}catch{}
let route='',tab='story',planet='Mars',guideMode='science',chat=[],busy=false,viewer,viewerEpoch=0,quiz={choice:null,evidence:null,submitted:false},modalTrigger,worldArtifact=null,chapter=0;
const completed=()=>artifacts.filter(a=>passport[a.id]?.completed).length;
const artifact=()=>artifacts.find(a=>a.id===route.split('/')[1]);
const refsHtml=ids=>ids.map(id=>`<button class="source-chip" data-source="${id}">${icon('book',14)} ${esc(sources[id].title)} ${icon('arrow',12)}</button>`).join('');
const primary=(text,href,extra='')=>`<a class="button primary ${extra}" href="${href}">${text}${icon('arrow')}</a>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function save(){try{localStorage.setItem('echoes-passport',JSON.stringify(passport));}catch{toast('Your browser could not save progress. You can still explore.');}}
function navigate(path){if(location.hash.slice(1)===path){route=path;render();window.scrollTo(0,0);}else location.hash=path;}

function header(){return `<header class="site-header"><a class="brand" href="#home" aria-label="ECHOES home"><span class="brand-mark">${icon('spark',27)}</span>ECHOES<span class="brand-sub">THE FORGOTTEN WORLDS</span></a><nav aria-label="Main navigation"><a href="#explore" class="${['atlas','explore'].includes(route)?'active':''}">The atlas</a><a href="#collection" class="${route==='collection'?'active':''}">The artifacts</a><a href="#about" class="${route==='about'?'active':''}">Our approach</a></nav><a class="passport-link" href="#passport">${icon('book',17)}<span>Explorer passport</span><b>${completed().toString().padStart(2,'0')}</b></a><button class="mobile-menu icon-button" aria-label="Open navigation" data-action="menu">${icon('menu')}</button></header>`;}
function footer(){return `<footer><a class="brand" href="#home">${icon('spark',26)} ECHOES</a><p>Made of curiosity. Grounded in evidence.</p><div><a href="#sources">Sources & credits ${icon('arrow',13)}</a><span>NASA open resources · Independent educational project</span></div></footer>`;}
function card(a,index){return `<a href="#artifact/${a.id}" class="artifact-card"><div class="card-image"><img src="assets/${a.image}" alt="${esc(a.name)} mission photograph" loading="lazy"><span class="small-pill">${a.world==='Moon'?'◐':'◉'} ${a.world}</span><span class="card-number">0${index+1}</span><span class="card-open">${icon('arrow',22)}</span></div><div class="card-meta"><span>${a.tag}</span><span>${a.years}</span></div><h3>${a.name}</h3><p>${a.subtitle}</p><span class="card-theme">${a.theme} ${icon('right',14)}</span></a>`;}
function home(){return `<main id="main"><section class="hero"><img class="hero-landscape" src="assets/mars-landscape.jpg" alt="Opportunity’s panoramic view of Victoria crater on Mars"><div class="hero-shade"></div><div class="hero-topline"><span><i class="status-dot"></i> A NEW WAY TO EXPLORE OLD WORLDS</span><span>EST. ON EARTH / EXPLORING BEYOND</span></div><div class="hero-copy"><span class="eyebrow">SPACE ARCHAEOLOGY, REIMAGINED</span><h1>Their missions ended.<br><em>Their stories didn’t.</em></h1><p>Somewhere on the Moon and Mars, our machines<br class="desktop"> are still waiting. Go discover what they left us.</p><div class="hero-actions">${primary('Begin your exploration','#explore')}<a href="#artifact/opportunity" class="text-link">Meet Opportunity ${icon('right',16)}</a></div></div><div class="hero-coordinate"><span>01 / MERIDIANI PLANUM</span><span>MARS · OPPORTUNITY MISSION ARCHIVE</span></div><div class="hero-bottom"><div><b>02</b><span>WORLDS TO EXPLORE</span></div><div><b>03</b><span>STORIES TO UNCOVER</span></div><div><span class="orbit-symbol">✳</span><span>REAL NASA EVIDENCE</span></div><a href="#collection">SCROLL TO DISCOVER <span>↓</span></a></div><div class="image-credit">Victoria crater panorama · NASA/JPL-Caltech/Cornell</div></section><section class="intro-strip"><span class="eyebrow">LEFT BEHIND. NEVER FORGOTTEN.</span><p>They crossed worlds for us.<br>Now it’s our turn to <em>listen.</em></p><span class="intro-small">An interactive collection of extraordinary machines<br>and the science they made possible.</span></section><section class="section collection-section"><div class="section-top"><div><span class="eyebrow">THE COLLECTION / 001—003</span><h2>Every artifact has an echo.</h2></div><a class="text-link" href="#collection">Explore the collection ${icon('arrow',17)}</a></div><div class="artifact-grid">${artifacts.map(card).join('')}</div></section><section class="how-section section"><div><span class="eyebrow">MORE THAN A MUSEUM</span><h2>Curiosity is<br>your only equipment.</h2><p>Follow a question from a spacecraft’s instruments to the real evidence behind its discoveries.</p><a class="text-link" href="#about">How ECHOES works ${icon('arrow',17)}</a></div><div class="how-steps">${[['01','globe','Find a forgotten world','Locate real mission sites on the Moon and Mars.'],['02','cube','Get closer to history','Turn NASA spacecraft models and inspect their instruments.'],['03','scan','Follow the evidence','Solve an investigation and collect your discoveries.']].map(x=>`<div><span>${x[0]}</span>${icon(x[1],25)}<section><h3>${x[2]}</h3><p>${x[3]}</p></section></div>`).join('')}</div></section><section class="closing"><span class="eyebrow">YOUR NEXT DISCOVERY IS WAITING</span><h2>There’s a whole story<br>in the silence.</h2>${primary('Find your first artifact','#explore')}</section></main>`;}

function collection(){return `<main id="main" class="section page"><span class="eyebrow">THE COLLECTION</span><div class="page-heading"><h1>Small machines.<br><em>Extraordinary legacies.</em></h1><p>Three artifacts. Three ways to understand another world.<br>Choose a story and follow its evidence.</p></div><div class="artifact-grid">${artifacts.map(card).join('')}</div><aside class="note">${icon('book')} A living collection, built from historical records. Photographs have dates; models are engineering illustrations.</aside></main>`;}
function atlas(){const list=artifacts.filter(a=>a.world===planet);return `<main id="main" class="atlas-page"><div class="atlas-copy"><span class="eyebrow">THE LOST WORLDS ATLAS</span><h1>Pick a world.<br><em>Find a story.</em></h1><p>Explore the places where human curiosity left its mark.</p><div class="segmented" aria-label="Select world">${['Moon','Mars'].map(x=>`<button data-world="${x}" class="${planet===x?'selected':''}" aria-pressed="${planet===x}">${x==='Moon'?'◐':'◉'} ${x}</button>`).join('')}</div><div class="atlas-sites">${list.map(a=>`<a href="#artifact/${a.id}" class="site-row"><span class="site-dot"></span><div><b>${a.name}</b><span>${a.place}</span></div><span>${a.years}</span>${icon('arrow',18)}</a>`).join('')}</div><p class="muted atlas-note">${icon('pin',15)} Markers indicate documented artifact locations for orientation.<br>Landing and final rover positions are different places.</p></div><div class="globe-area"><div id="globe-canvas" class="globe-canvas"><img class="globe-poster" src="assets/${planet.toLowerCase()}.jpg" alt="${planet} globe from NASA imagery"></div><span class="globe-label">${planet.toUpperCase()} / ${planet==='Mars'?'THE RED PLANET':'OUR NEAREST NEIGHBOR'}</span><div class="globe-controls"><span>${icon('scan',15)} DRAG TO ROTATE · SCROLL TO ZOOM</span><button class="icon-button" data-viewer="reset" aria-label="Reset globe">${icon('reset',17)}</button></div></div></main>`;}

function exhibit(a){return `<main id="main" class="exhibit-page"><div class="exhibit-top"><a class="text-link" href="#collection">${icon('back',15)} The collection</a><span class="eyebrow">${a.code}</span><span class="small-pill">${a.world} / ${a.tag}</span></div><div class="exhibit-heading"><div><h1>${a.name}<span class="status-dot"></span></h1><p>${a.subtitle}</p></div><div class="exhibit-location">${icon('pin',17)}<div>${a.place}<small>${a.coordinate}</small></div></div></div><div class="exhibit-layout"><section class="object-panel"><div class="object-top"><span>${icon('cube',16)} ARTIFACT EXPLORER</span><div><button data-action="show-photo" class="small-button">Photograph</button><button data-action="load-model" class="small-button active">3D model</button></div></div><div class="model-area" id="model-area"><img id="model-poster" src="assets/${a.image}" alt="${a.name} historical mission photograph"><div class="model-load" id="model-load"><button class="button primary" data-action="load-model">${icon('cube')} Load 3D artifact</button><small>${a.id==='insight'?'22':a.id==='opportunity'?'12':'0.7'} MB · NASA engineering model</small></div><div class="model-loading" hidden>Loading NASA model…</div></div><div class="viewer-controls"><span id="viewer-hint">EXPLORE AN ORIGINAL NASA MODEL</span><div><button class="icon-button" data-viewer="rotate" aria-label="Toggle automatic rotation">${icon('play',15)}</button><button class="icon-button" data-viewer="zoom-in" aria-label="Zoom in">${icon('plus',16)}</button><button class="icon-button" data-viewer="zoom-out" aria-label="Zoom out">${icon('minus',16)}</button><button class="icon-button" data-viewer="reset" aria-label="Reset view">${icon('reset',16)}</button></div></div><div class="component-buttons">${a.hotspots.map((h,i)=>`<button data-hotspot="${i}"><span>0${i+1}</span>${h.name}${icon('plus',13)}</button>`).join('')}</div><p class="model-note">${a.modelNote}</p></section><section class="exhibit-information"><div class="tabs" role="tablist" aria-label="Exhibit sections">${[['story','The story'],['ask','Ask Echo'],['evidence','Evidence']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'selected':''}">${label}${id==='ask'?'<i class="tiny-dot"></i>':''}</button>`).join('')}</div><div class="tab-content" role="tabpanel" tabindex="0">${tab==='story'?story(a):tab==='ask'?ask(a):evidence(a)}</div></section></div><section class="investigation-banner"><div class="investigation-icon">${icon('scan',31)}</div><div><span class="eyebrow">SPACE ARCHAEOLOGIST MODE</span><h2>${a.question}</h2><p>Inspect the clues. Make a discovery. Earn your expedition stamp.</p></div>${primary(passport[a.id]?.completed?'Revisit investigation':'Start investigation',`#investigation/${a.id}`)}</section></main>`;}
function story(a){return `<span class="eyebrow">THE MISSION / IN THREE CHAPTERS</span><h2>${a.intro}</h2><div class="timeline">${a.chapters.map((c,i)=>`<article><span class="timeline-index">0${i+1}</span><div><span class="eyebrow">${c.year}</span><h3>${c.title}</h3><p>${c.text}</p><button class="evidence-link" data-source="${c.ref}">View evidence ${icon('arrow',13)}</button></div></article>`).join('')}</div><div class="exhibit-stats">${a.stats.map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('')}</div>`;}
function ask(a){return `<div class="guide-heading"><span class="guide-avatar">${icon('spark',24)}</span><div><h3>Meet Echo</h3><p>Your source-based mission guide</p></div><span class="local-badge">ON DEVICE</span></div><div class="segmented guide-mode"><button class="${guideMode==='science'?'selected':''}" data-mode="science">Science explanation</button><button class="${guideMode==='story'?'selected':''}" data-mode="story">Story voice</button></div><p class="guide-disclosure">${guideMode==='story'?'First-person narration is dramatized, based on the evidence. It is not a historical quotation.':'Answers are selected from curated NASA evidence. This free guide uses local topic matching, not generative AI.'}</p><div class="chat-log" aria-live="polite">${chat.length?chat.map(m=>`<div class="chat-message ${m.role}">${m.role==='guide'?`<span class="chat-label">${icon('spark',12)} ECHO / ${m.story?'DRAMATIZED NARRATION':'EVIDENCE GUIDE'}</span>`:''}<p>${esc(m.text)}</p>${m.refs?`<div class="answer-refs">${refsHtml(m.refs)}</div>`:''}</div>`).join(''):`<div class="chat-message guide"><p>There’s a lot to uncover about ${a.name}. Ask about the mission, its instruments, its discoveries, or what happened next.</p></div>`}</div><div class="suggestions">${suggestions(a.id).map(q=>`<button data-question="${esc(q)}">${q} ${icon('plus',12)}</button>`).join('')}</div><form id="question-form"><label class="sr-only" for="question">Ask about ${a.name}</label><input id="question" maxlength="300" placeholder="What would you like to discover?" autocomplete="off" required><button class="send-button" aria-label="Ask Echo">${icon('send',19)}</button></form><span class="chat-footnote">Free to explore. Your questions stay in this browser.</span>`;}
function evidence(a){return `<span class="eyebrow">THE EVIDENCE LENS</span><h2>Good stories leave a trail.</h2><p class="muted">Follow the observations and records behind this exhibit.</p><figure class="evidence-image"><img src="assets/${a.evidenceImage}" alt="${a.id==='opportunity'?'Small mineral spherules photographed by Opportunity':a.id==='eagle'?'Annotated orbital image of the Apollo 11 site':'Dated orbital image showing InSight on Mars'}"><figcaption>${a.id==='opportunity'?'April 19, 2004 · frame about 3 cm across':a.id==='eagle'?'LROC orbital image · annotated landing site':'HiRISE · acquired October 23, 2024'}<button data-source="${a.evidence}">Original record ${icon('arrow',12)}</button></figcaption></figure>${a.refs.map((r,i)=>`<button class="evidence-card" data-source="${r}"><span>0${i+1}</span><div><b>${sources[r].title}</b><small>${sources[r].org}</small></div>${icon('arrow',17)}</button>`).join('')}<p class="small-note">Source summaries are paraphrased. Capture dates describe historical observations, not live views.</p>`;}

function investigation(a){const done=quiz.submitted&&gradeInvestigation(a.id,quiz.choice,quiz.evidence);return `<main id="main" class="section page investigation-page"><a class="text-link" href="#artifact/${a.id}">${icon('back',15)} Back to ${a.name}</a><div class="investigation-header"><span class="eyebrow">FIELD INVESTIGATION / ${a.name.toUpperCase()}</span><span class="small-pill">${done?'COMPLETE':'3 STEPS · ABOUT 5 MINUTES'}</span></div><h1>${done?'A discovery worth keeping.':a.question}</h1>${done?`<div class="discovery-result"><div class="stamp">${icon('check',48)}<span>VERIFIED EXPLORER</span></div><h2>You followed the evidence.</h2><p>${a.why}</p><div class="answer-refs">${refsHtml([a.evidence])}</div><div class="hero-actions">${primary('View your passport','#passport')}<a class="text-link" href="#explore">Next expedition ${icon('arrow',17)}</a></div></div>`:`<div class="investigation-grid"><section><div class="step-heading"><span>01</span><h2>Observe the evidence</h2></div><figure class="clue-image"><img src="assets/${a.evidenceImage}" alt="Evidence photograph for ${a.name}"><figcaption>${a.id==='opportunity'?'Mineral spherules · Opportunity · April 19, 2004':a.id==='eagle'?'Apollo 11 site · LROC orbital observation':'InSight · HiRISE observation · October 23, 2024'}</figcaption></figure><div class="clue-text"><span class="eyebrow">FIELD NOTES</span><p>${a.id==='opportunity'?'The photograph shows small mineral spheres. NASA’s record identifies these as hematite-rich concretions. Use the mineral evidence and its interpretation together.':a.id==='eagle'?'Compare the orbital photograph with the complete Lunar Module model. Read which spacecraft stage left with the astronauts.': 'The photograph shows the retired lander from orbit. For the interior investigation, open the science record and consider what seismic waves can reveal.'}</p><button class="evidence-link" data-source="${a.evidence}">Read the source ${icon('arrow',14)}</button></div></section><section><div class="step-heading"><span>02</span><h2>Choose your conclusion</h2></div><div class="quiz-choices" role="radiogroup" aria-label="Choose a scientific conclusion">${a.choices.map((c,i)=>`<button role="radio" aria-checked="${quiz.choice===i}" data-choice="${i}" class="${quiz.choice===i?'selected':''}"><span>${String.fromCharCode(65+i)}</span>${c}<i></i></button>`).join('')}</div><div class="step-heading"><span>03</span><h2>Back it with a source</h2></div><p class="muted">Which record directly supports your conclusion?</p><div class="quiz-choices evidence-choices" role="radiogroup" aria-label="Choose supporting evidence">${[a.evidence,...a.refs.filter(r=>r!==a.evidence).slice(0,1)].map(r=>`<button role="radio" aria-checked="${quiz.evidence===r}" data-evidence="${r}" class="${quiz.evidence===r?'selected':''}">${icon('book',17)}<span class="source-choice">${sources[r].title}<small>${sources[r].org}</small></span><i></i></button>`).join('')}</div>${quiz.submitted?`<div class="feedback" role="status">${quiz.choice!==a.correct?'Take another look: distinguish what the evidence supports from what it cannot tell us.':'Your conclusion is right. Find the source that most directly supports it.'}</div>`:''}<button class="button primary submit-investigation" data-action="submit-investigation" ${quiz.choice===null||!quiz.evidence?'disabled':''}>Verify my discovery ${icon('check',19)}</button></section></div>`}</main>`;}

function passportPage(){return `<main id="main" class="section page passport-page"><span class="eyebrow">YOUR EXPLORER PASSPORT</span><div class="page-heading"><h1>Collected curiosity.</h1><p>A record of the stories you’ve uncovered<br>and the evidence you followed.</p></div><div class="passport-summary"><span>${icon('globe',36)}</span><div><b>${completed()} <small>/ 3 investigations</small></b><p>${completed()===3?'All three expedition stamps collected. Keep asking questions.':'Your next discovery is just a question away.'}</p></div><button class="button outline" data-action="export">${icon('download',17)} Export discoveries</button></div><div class="passport-grid">${artifacts.map(a=>`<article class="passport-card ${passport[a.id]?.completed?'earned':''}"><div class="passport-stamp">${icon(passport[a.id]?.completed?'check':'scan',35)}<span>${a.world}</span></div><span class="eyebrow">${a.tag}</span><h2>${a.name}</h2><p>${passport[a.id]?.completed?a.why:'An investigation is waiting to be uncovered.'}</p><span class="stamp-date">${passport[a.id]?.completed?`COMPLETED ${esc(passport[a.id].date)}`:'STAMP NOT YET EARNED'}</span><a class="text-link" href="#investigation/${a.id}">${passport[a.id]?.completed?'Revisit discovery':'Begin investigation'} ${icon('arrow',16)}</a></article>`).join('')}</div><div class="passport-bottom"><p>Progress is saved on this device. Export a copy to keep your discoveries.</p><button class="muted-link" data-action="reset-passport">Reset passport</button></div></main>`;}
function about(){return `<main id="main" class="section page about-page"><span class="eyebrow">OUR APPROACH</span><h1>A little wonder.<br><em>A lot of evidence.</em></h1><p class="about-intro">Spacecraft don’t need to be operating to have something to teach us. ECHOES connects their stories to the hardware, observations, and records that make them meaningful.</p><div class="principle-grid">${[['cube','Real hardware','Turn downloadable NASA engineering models. See the difference between a design illustration and a dated photograph.'],['book','Traceable stories','Open the Evidence Lens on a claim. Follow the link to its original mission record, image caption, or scientific explanation.'],['scan','Active discovery','Use evidence to answer a question. Earn a stamp by making a supported conclusion, with feedback along the way.'],['spark','A free mission guide','Echo matches your question to curated explanations on this device. It does not use paid services or generative AI. Story voice is clearly marked as dramatized.']].map(x=>`<article>${icon(x[0],28)}<h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</div><section class="legacy-section"><span class="eyebrow">THE LEGACY CONSTELLATION</span><h2>Different machines. Shared curiosity.</h2><div class="legacy-grid">${artifacts.map(a=>`<a href="#artifact/${a.id}"><span>${a.world}</span><h3>${a.name}</h3><div class="legacy-line"></div><b>${a.legacy}</b><p>${a.legacyText}</p>${icon('arrow',19)}</a>`).join('')}</div></section><aside class="note">${icon('globe')} ECHOES is an independent educational project using NASA open resources. No NASA endorsement is implied. There are no accounts, analytics, paid APIs, or requests carrying your questions.</aside></main>`;}
function sourcesPage(){return `<main id="main" class="section page sources-page"><span class="eyebrow">THE MISSION ARCHIVE</span><h1>Follow every story<br><em>to its source.</em></h1><p class="muted">Primary NASA mission records and instrument-team imagery. Summaries are paraphrased; model and image credits are preserved below.</p><div class="source-grid">${Object.entries(sources).map(([id,s])=>`<article><span class="eyebrow">${s.org}</span><h2>${s.title}</h2><p>${s.summary}</p><a class="text-link" target="_blank" rel="noopener noreferrer" href="${s.url}">Open original source ${icon('arrow',15)}</a></article>`).join('')}</div><h2 class="credits-heading">Images & 3D models</h2><div id="asset-credits"><p class="muted">Loading asset credits…</p></div><p class="small-note">Three.js 0.180.0 · MIT license · <a href="vendor/THREE-LICENSE.txt">View license</a>. NASA media use: <a href="https://www.nasa.gov/nasa-brand-center/images-and-media/" target="_blank" rel="noopener">Guidelines</a>.</p></main>`;}

function render(){viewerEpoch++;viewer?.dispose();viewer=null;gameplay.mount();}
async function loadGlobe(){const epoch=viewerEpoch;try{const {createViewer}=await import('./viewer.js');if(epoch!==viewerEpoch)return;const target=$('#globe-canvas');const result=await createViewer(target,{world:planet,onSelect:id=>navigate(`artifact/${id}`)});if(epoch!==viewerEpoch){result?.dispose();return;}viewer=result;target.querySelector('img')?.remove();}catch{toast('Interactive globe unavailable. All sites are accessible in the list.');}}
async function loadModel(){if(viewer||busy)return;const a=artifact();if(!a)return;busy=true;const epoch=viewerEpoch;$('#model-load').hidden=true;$('.model-loading').hidden=false;try{const {createViewer}=await import('./viewer.js');if(epoch!==viewerEpoch)return;const result=await createViewer($('#model-area'),{artifact:a,onSelect:i=>document.querySelector(`[data-hotspot="${i}"]`)?.click()});if(epoch!==viewerEpoch){result?.dispose();return;}viewer=result;$('#model-poster').hidden=true;$('.model-loading').hidden=true;$('#viewer-hint').textContent='DRAG TO ROTATE · SELECT A NUMBER';}catch(error){console.warn('Model load failed:',error?.message);if(epoch===viewerEpoch){$('#model-load').hidden=false;$('.model-loading').hidden=true;toast('3D could not load. The photograph, instrument guide, and evidence remain available.');}}finally{busy=false;}}
async function loadCredits(){try{const manifest=await fetch('credits.json').then(r=>r.json());if(!$('#asset-credits'))return;$('#asset-credits').innerHTML=manifest.assets.map(a=>`<div class="asset-credit"><span>${esc(a.kind)}</span><div><b>${esc(a.file)}</b><p>${esc(a.note||'')}</p><small>${esc(a.credit)}</small></div><a href="${esc(a.source)}" target="_blank" rel="noopener noreferrer" aria-label="Source for ${esc(a.file)}">${icon('arrow',18)}</a></div>`).join('');}catch{if($('#asset-credits'))$('#asset-credits').innerHTML='<p>See the ASSETS.json file in the project for full asset provenance.</p>';}}
function openModal(title,content){modalTrigger=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('modal-open');$('.modal-close').focus();}
function closeModal(){$('#overlay').innerHTML='';document.body.classList.remove('modal-open');modalTrigger?.focus();}
function openSource(id){const s=sources[id];if(!s)return;openModal(s.title,`<span class="eyebrow">EVIDENCE LENS / PRIMARY SOURCE</span><div class="source-modal-icon">${icon('book',32)}</div><h2>${s.title}</h2><span class="source-org">${s.org}</span><p>${s.summary}</p><div class="source-paraphrase">This is a paraphrased source summary. Open the original record for its full wording and context.</div><a class="button primary" href="${s.url}" target="_blank" rel="noopener noreferrer">Read original NASA record ${icon('arrow',18)}</a>`);}
function refreshInfo(){const a=artifact();if(!a)return;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab);});$('.tab-content').innerHTML=tab==='story'?story(a):tab==='ask'?ask(a):evidence(a);}
function changeTab(value){tab=value;refreshInfo();}
function submitQuestion(question){const a=artifact();if(!a||!question.trim())return;const answer=answerQuestion(a.id,question,guideMode);chat.push({role:'user',text:question},{role:'guide',...answer,story:guideMode==='story'});chat=chat.slice(-12);refreshInfo();$('.chat-log')?.scrollTo(0,100000);$('#question')?.focus();}
document.addEventListener('click',event=>{if(event.target.closest('.skip')){event.preventDefault();const main=$('#main');main.tabIndex=-1;main.focus();main.scrollIntoView();return;}const target=event.target.closest('button,[data-source],.modal-backdrop');if(!target)return;
 if(target.dataset.source){openSource(target.dataset.source);return;}
 if(target.dataset.tab){changeTab(target.dataset.tab);return;}
 if(target.dataset.world){planet=target.dataset.world;worldArtifact=null;chapter=0;render();return;}
 if(target.dataset.worldStory){selectWorldStory(target.dataset.worldStory);return;}
 if(target.dataset.chapter!==undefined){chapter=+target.dataset.chapter;updateWorldStory();return;}
 if(target.dataset.mode){guideMode=target.dataset.mode;refreshInfo();return;}
 if(target.dataset.question){submitQuestion(target.dataset.question);return;}
 if(target.dataset.hotspot!==undefined){const a=artifact(),h=a?.hotspots[+target.dataset.hotspot];if(h)openModal(h.name,`<span class="eyebrow">COMPONENT GUIDE / ${a.name.toUpperCase()}</span><div class="source-modal-icon">${icon('cube',32)}</div><h2>${h.name}</h2><p>${h.text}</p>${refsHtml([h.ref])}<p class="small-note">The engineering model and this accessible component guide describe the same hardware.</p>`);return;}
 if(target.dataset.viewer){if(!viewer){toast('Load the 3D artifact to use these controls.');return;}const action=target.dataset.viewer;if(action==='reset')viewer.reset();if(action==='rotate'){const active=viewer.rotate();target.setAttribute('aria-pressed',active);}if(action==='zoom-in')viewer.zoom(0.85);if(action==='zoom-out')viewer.zoom(1.15);return;}
 if(target.dataset.choice!==undefined){quiz.choice=+target.dataset.choice;quiz.submitted=false;render();return;}
 if(target.dataset.evidence){quiz.evidence=target.dataset.evidence;quiz.submitted=false;render();return;}
 const action=target.dataset.action;
 if(action==='load-model')loadModel();
 if(action==='next-chapter'){chapter=Math.min(2,chapter+1);updateWorldStory();}
 if(action==='previous-chapter'){chapter=Math.max(0,chapter-1);updateWorldStory();}
 if(action==='close-story'){worldArtifact=null;chapter=0;updateWorldStory();viewer?.reset();if(matchMedia('(max-width:800px)').matches)window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='show-photo'){viewerEpoch++;viewer?.dispose();viewer=null;$('#model-poster').hidden=false;$('#model-load').hidden=false;$('.model-loading').hidden=true;$('#viewer-hint').textContent=artifact().imageCredit;}
 if(action==='close-modal')closeModal();
 if(target.classList.contains('modal-backdrop')&&event.target===target)closeModal();
 if(action==='menu'){openModal('Navigation',`<h2>Your expedition</h2><nav class="mobile-nav"><a href="#explore">The atlas ${icon('arrow')}</a><a href="#collection">The artifacts ${icon('arrow')}</a><a href="#about">Our approach ${icon('arrow')}</a><a href="#passport">Explorer passport ${icon('book')}</a></nav>`);}
 if(action==='submit-investigation'){const a=artifact();quiz.submitted=true;if(gradeInvestigation(a.id,quiz.choice,quiz.evidence)){passport[a.id]={completed:true,date:new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})};save();}render();if(gradeInvestigation(a.id,quiz.choice,quiz.evidence))window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='export'){const records=artifacts.filter(a=>passport[a.id]?.completed).map(a=>({artifact:a.name,completed:passport[a.id].date,conclusion:a.choices[a.correct],source:sources[a.evidence].url}));const blob=new Blob([JSON.stringify({project:'ECHOES — The Forgotten Worlds',discoveries:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='echoes-discoveries.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your discoveries have been exported.');}
 if(action==='reset-passport')openModal('Reset explorer passport',`<span class="eyebrow">YOUR DEVICE / YOUR PROGRESS</span><h2>Start a fresh expedition?</h2><p>This clears the three stamps saved in this browser. Export your discoveries first if you want to keep a copy.</p><button class="button primary" data-action="confirm-reset">Reset my passport</button>`);
 if(action==='confirm-reset'){passport={};save();closeModal();render();toast('Your passport is ready for a fresh expedition.');}
});
document.addEventListener('submit',e=>{if(e.target.id==='question-form'){e.preventDefault();submitQuestion($('#question').value);}});
document.addEventListener('keydown',e=>{if($('.echo-chat-panel'))return;if(document.body.classList.contains('game-mode')&&!$('.modal'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&['tab','radio'].includes(e.target.getAttribute('role'))){e.preventDefault();const group=e.target.parentElement,items=[...group.querySelectorAll('button')],index=items.indexOf(e.target),next=items[(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:items.length-1))%items.length],tabId=next.dataset.tab,choice=next.dataset.choice,evidenceId=next.dataset.evidence;next.click();const fresh=tabId?document.querySelector(`[data-tab="${tabId}"]`):choice!==undefined?document.querySelector(`[data-choice="${choice}"]`):document.querySelector(`[data-evidence="${evidenceId}"]`);fresh?.focus();return;}if(!$('.modal'))return;if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const items=[...$('.modal').querySelectorAll('button,a,input')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();route=location.hash.slice(1)||'home';tab='story';chat=[];quiz={choice:null,evidence:null,submitted:false};busy=false;render();window.scrollTo(0,0);});
function worldPage(){return `<main id="main" class="world-page ${worldArtifact?'reading-story':''}"><div class="world-toolbar"><a href="#home" class="text-link">${icon('back',14)} Back to Earth</a><div class="segmented" aria-label="Choose an explorable world">${['Moon','Mars'].map(w=>`<button data-world="${w}" class="${planet===w?'selected':''}" aria-pressed="${planet===w}">${w==='Moon'?'◐':'◉'} ${w}</button>`).join('')}</div><span class="world-status"><i class="status-dot"></i> EXPEDITION / ${planet.toUpperCase()}</span></div><div id="world-canvas" class="world-canvas"><img class="world-fallback" src="assets/${planet.toLowerCase()}.jpg" alt="${planet} from NASA imagery"><span class="world-loading">Preparing your world…</span></div><section class="world-narrative" aria-live="polite">${worldNarrative()}</section><div class="world-scene-controls"><span>DRAG TO ORBIT · SELECT A SPACECRAFT</span><div><button class="icon-button" data-viewer="zoom-in" aria-label="Move closer to the world">${icon('plus',16)}</button><button class="icon-button" data-viewer="zoom-out" aria-label="Move away from the world">${icon('minus',16)}</button><button class="icon-button" data-viewer="reset" aria-label="Reset world view">${icon('reset',16)}</button></div></div><div class="world-artifact-dock"><div><span class="eyebrow">CHOOSE AN ECHO</span><span>${planet==='Mars'?'02 artifacts · two very different questions':'01 artifact · humanity’s first lunar landing'}</span></div>${artifacts.filter(a=>a.world===planet).map(a=>`<button class="world-artifact-button ${worldArtifact===a.id?'selected':''}" data-world-story="${a.id}"><img src="assets/${a.image}" alt=""><div><span>${a.tag}</span><b>${a.name}</b></div>${icon('arrow',20)}</button>`).join('')}<span class="world-scale-note">Artifact models are enlarged for discovery.<br>Locations are approximate. Surface markers are illustrative.</span></div></main>`;}
function worldNarrative(){const a=artifacts.find(x=>x.id===worldArtifact);if(!a)return `<div class="world-introduction"><span class="eyebrow">THE FORGOTTEN WORLDS / ${planet==='Moon'?'001':'002'}</span><h1>Some stories<br>are still<br><em>out there.</em></h1><p>${planet==='Mars'?'Two silent explorers. One world full of questions. Turn Mars and discover the machines that investigated its water and its heartbeat.':'A landing stage sits at Tranquility Base, a reminder of the first human footsteps on another world. Turn the Moon and find Eagle’s story.'}</p><div class="world-instruction">${icon('scan',22)}<span>Select a spacecraft on the globe<br>or choose an artifact below.</span></div><div class="world-intro-rule"></div><span class="world-chapter-note">Every echo leads back to real NASA evidence.</span></div>`;
 const s=stories[a.id][chapter];return `<article class="world-story"><div class="world-story-top"><span class="eyebrow">${a.name.toUpperCase()} / ECHO 0${chapter+1}</span><button class="icon-button" data-action="close-story" aria-label="Return to world exploration">${icon('close',16)}</button></div><div class="story-progress">${stories[a.id].map((_,i)=>`<button data-chapter="${i}" class="${i===chapter?'active':i<chapter?'read':''}" aria-label="Read chapter ${i+1}" aria-current="${i===chapter?'step':'false'}"></button>`).join('')}</div><h1>${s.title}</h1><p class="story-line">${s.line}</p><figure><img src="assets/${s.image}" alt="${esc(s.caption)}"><figcaption>${s.caption}</figcaption></figure><p class="story-narration">${s.text}</p><div class="story-authorship">DRAMATIZED NARRATION · SOURCE-BASED</div><button class="evidence-link" data-source="${s.ref}">${icon('book',14)} Follow the evidence ${icon('arrow',13)}</button><div class="world-story-actions"><button class="story-back" data-action="previous-chapter" ${chapter===0?'disabled':''} aria-label="Previous story chapter">${icon('back',17)}</button>${chapter<2?`<button class="button primary" data-action="next-chapter">Continue the story ${icon('right',17)}</button>`:primary('Explore the artifact',`#artifact/${a.id}`)}</div><span class="story-page-number">CHAPTER ${chapter+1} OF 3 / ${a.world.toUpperCase()}</span></article>`;}
function updateWorldStory(){const panel=$('.world-narrative');if(!panel)return;panel.innerHTML=worldNarrative();$('.world-page').classList.toggle('reading-story',!!worldArtifact);document.querySelectorAll('[data-world-story]').forEach(b=>b.classList.toggle('selected',b.dataset.worldStory===worldArtifact));panel.scrollTo({top:0,behavior:'smooth'});const heading=panel.querySelector('h1');if(worldArtifact&&heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function selectWorldStory(id){const a=artifacts.find(x=>x.id===id);if(!a)return;worldArtifact=id;chapter=0;updateWorldStory();viewer?.select?.(id);if(matchMedia('(max-width:800px)').matches)$('.world-narrative')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});}
async function loadWorld(){const epoch=viewerEpoch;try{const {createWorld}=await import('./world.js');if(epoch!==viewerEpoch)return;const target=$('#world-canvas'),result=await createWorld(target,{world:planet,onSelect:selectWorldStory});if(epoch!==viewerEpoch){result?.dispose();return;}viewer=result;target.querySelector('img')?.remove();target.querySelector('.world-loading')?.remove();if(worldArtifact)viewer.select(worldArtifact);}catch{const loading=$('.world-loading');if(loading)loading.textContent='Select an artifact below to read its story.';toast('3D is unavailable here. All stories are still accessible below.');}}
const gameplay=installGameUI({icon,esc,refsHtml,passport,save,onExport:()=>{const b=document.createElement('button');b.dataset.action='export';document.body.append(b);b.click();b.remove();}});
const artifactChat=createArtifactChat({icon,esc,getContext:()=>gameplay.activeArtifact});
route=location.hash.slice(1)||'home';render();
